import{z as A,x as d,o as t,c as B,q as E,j as s,D as e,d as r,s as n,S as l,b as o}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"早期启动","description":"","frontmatter":{"title":"早期启动","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/early-boot.md","filePath":"cs/early-boot.md","lastUpdated":1791063341000}'),p={name:"cs/early-boot.md"};function m(c,a,f,D,h,u){const i=d("Mermaid");return t(),B("div",null,[a[2]||(a[2]=E('<h1 id="早期启动" tabindex="-1">早期启动 <a class="header-anchor" href="#早期启动" aria-label="Permalink to &quot;早期启动&quot;">​</a></h1><div class="epigraph"><p>复位后引导程序把内核装入内存并跳转；内核解压、建页表、初始化中断与分配器，直到能够挂上根并创建 pid 1。</p><footer>—— 据 Tanenbaum MOS；Love；Bovet 对 Linux 启动链的整理</footer></div><p><a href="/cs/sysfs-proc">上一课</a>假定内核已在跑。<a href="/cs/kernel-user">内核与用户态</a> 说复位先进入内核。<a href="/cs/buddy-allocator">buddy</a> 与中断向量都需要有人第一次建好。缺口是<strong>早期启动链</strong>：固件/引导加载器 → 内核入口 → 解压 → <code>start_kernel</code> 量级的初始化顺序。不把每家 SoC 的 bootrom 写成手册。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CPU 复位时没有页表、没有驱动、没有 FS。引导加载器在实模式或固件环境读磁盘/网络，把内核映像放到约定物理地址，传递命令行与内存图。内核必须：开分页（<a href="/cs/paging-vm">分页</a> 的第一套表）、识别内存、初始化 buddy、中断控制器、调度器、VFS 根。缺口是这条因果顺序，而不是某个启动徽标。</p><p><span class="marginnote">启动链可以类比接力赛：每一棒只做一件事并把控制权交给下一棒——固件点亮硬件并找到磁盘上的引导程序，引导程序认识文件系统、装载内核映像，内核再自己搭好页表、中断与分配器。交接棒就是前一棒留下的内存图与命令行参数。</span></p><p><span class="marginnote">initramfs 是内存里的早期根，用于加载根设备模块再切到真根。设备树或 ACPI 描述板级硬件。本课合并这些，不当三篇。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>固件 → bootloader（如 GRUB、UEFI）→ 跳内核入口。入口：关干扰、建临时映射、解压缩。<code>start_kernel</code>：内存、调度、时间（jiffies 来源）、驱动子系统、挂载 initramfs、启动 pid 1 前的 rest_init。失败通常 panic，因为还没有用户空间可报错。命令行可指定 <code>root=</code>。</p><p><span class="marginnote">为什么这一阶段出错只能 panic：此时没有用户空间、没有日志文件、常常连时钟都没接好——内核无处可报、无人可问，只能打一行 panic 信息停机。桌面机上这行字经常一闪而过，最常见的原因之一是根设备的驱动没进 initramfs。</span></p>',10)),(t(),s(l,null,{default:e(()=>[n(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20RST%5B%22%E5%A4%8D%E4%BD%8D%2F%E5%9B%BA%E4%BB%B6%22%5D%20--%3E%20BL%5B%22%E5%BC%95%E5%AF%BC%E5%8A%A0%E8%BD%BD%E5%99%A8%22%5D%0A%20%20BL%20--%3E%20K%5B%22%E5%86%85%E6%A0%B8%E5%85%A5%E5%8F%A3%E4%B8%8E%E8%A7%A3%E5%8E%8B%22%5D%0A%20%20K%20--%3E%20SK%5B%22start_kernel%22%5D%0A%20%20SK%20--%3E%20RAMFS%5B%22initramfs%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[r("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,"早期启动把组成课的「上电」接到 OS 对象的第一次出现：没有 buddy 就没有后续缺页；没有中断就没有 DMA 完成。用户/内核分裂的第一套内核映射在这里建立。不要把安全启动密钥管理写成攻击或绕过指南；只承认引导路径可被验签。",-1)),(t(),s(l,null,{default:e(()=>[n(i,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20EGG%5B%22%E9%B8%A1%E7%94%9F%E8%9B%8B%E9%97%AE%E9%A2%98%EF%BC%9A%E8%AF%BB%E7%A3%81%E7%9B%98%E8%A6%81%E9%A9%B1%E5%8A%A8%EF%BC%8C%E9%A9%B1%E5%8A%A8%E5%8D%B4%E8%A3%85%E5%9C%A8%E7%A3%81%E7%9B%98%E7%9A%84%E7%9C%9F%E6%A0%B9%E9%87%8C%22%5D%20--%3E%20IR%5B%22initramfs%EF%BC%9A%E5%86%85%E5%AD%98%E9%87%8C%E7%9A%84%E4%B8%B4%E6%97%B6%E6%A0%B9%22%5D%0A%20%20IR%20--%3E%20MOD%5B%22%E4%BB%8E%E5%86%85%E5%AD%98%E5%8A%A0%E8%BD%BD%E5%AD%98%E5%82%A8%E9%A9%B1%E5%8A%A8%22%5D%0A%20%20MOD%20--%3E%20MNT%5B%22%E6%8C%82%E8%BD%BD%E7%9C%9F%E6%AD%A3%E7%9A%84%E6%A0%B9%E8%AE%BE%E5%A4%87%22%5D%0A%20%20MNT%20--%3E%20SW%5B%22%E5%88%87%E6%8D%A2%E6%A0%B9%EF%BC%88switch_root%EF%BC%89%22%5D%0A%20%20SW%20--%3E%20PID1%5B%22%E5%90%AF%E5%8A%A8%20pid%201%EF%BC%8C%E4%BA%A4%E6%A3%92%E7%94%A8%E6%88%B7%E7%A9%BA%E9%97%B4%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=E('<p><span class="marginnote">这张图回答「为什么非要 initramfs」：根设备驱动本身是文件，装在根文件系统里，不挂根就加载不了它——死循环。initramfs 是打包进内核映像、开机就在内存里的一小套根，专管把真根的驱动带进内核，鸡生蛋的环就此解开。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 kexec 的全部协议。不保证嵌入式无 bootloader（有的直接进内核）。下一课：内核把 CPU 交给用户空间的 pid 1，由它挂真根、拉服务。</p><p>后课默认：内核已能调度并有早期根。用户空间的第一个进程，下一课 init。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>引导加载器装核；内核建页表与分配器后才能挂根。</li><li>initramfs 解决「根设备驱动还不在根上」的环。</li><li>pid 1 与真根是 init 课的缺口。</li><li>出处：Tanenbaum <em>MOS</em>；Love, <em>LKD</em>；Bovet and Cesati, <em>ULK</em>。</li></ul>',6))])}const C=A(p,[["render",m]]);export{b as __pageData,C as default};
